package com.hbm.client.entity.maskman;
import com.hbm.entity.mob.maskman.MaskMan;import com.hbm.client.model.*;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.model.EntityModel;import net.minecraft.client.renderer.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;
/** Exact ModelMaskMan OBJ parts, source RenderLiving's scaleFactor=.0625 (not the frame partial), authored UVs and IOU texture switch. */
final class MaskManModel extends EntityModel<MaskMan>{private MaskMan entity;private float yaw;MultiBufferSource buffers;MaskManModel(){super(RenderType::entityCutout);}@Override public void setupAnim(MaskMan mob,float limb,float amount,float age,float yaw,float pitch){entity=mob;this.yaw=yaw;}private static WavefrontMesh mesh(){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse("hbm:models/mobs/maskman.obj"));}private static void part(String name,PoseStack p,VertexConsumer out,int light,int overlay,int color){LegacyObjRenderer.renderOnly(mesh(),p,out,light,overlay,color,LegacyObjRenderer.Convention.FORGE,name);}@Override public void renderToBuffer(PoseStack p,VertexConsumer out,int light,int overlay,int color){p.pushPose();p.translate(0,-.0068125,0);p.mulPose(Axis.XP.rotationDegrees(180));p.translate(0,-1.5F,0);p.mulPose(Axis.YN.rotationDegrees(90));float scale=.0625F,limb=entity.walkAnimation.position(),amount=entity.walkAnimation.speed(),previous=entity.walkAnimation.speed(0);float f7=limb-amount*(1-scale),f6=(previous+(amount-previous)*scale)*.5F;float swing=(float)Math.toDegrees(Mth.cos(f7/2F+(float)Math.PI)*1.4F*f6);p.mulPose(Axis.XP.rotationDegrees(swing*-.1F));part("Torso",p,out,light,overlay,color);limb("LLeg",p,out,light,overlay,color,-.5F,1.75F,-.5F,swing);limb("RLeg",p,out,light,overlay,color,-.5F,1.75F,.5F,-swing);limb("LArm",p,out,light,overlay,color,-.5F,3.75F,-1.5F,swing*.25F);limb("RArm",p,out,light,overlay,color,-.5F,3.75F,1.5F,-swing*.25F);p.pushPose();p.translate(.5F,4,0);p.mulPose(Axis.YN.rotationDegrees(yaw));if(entity.getHealth()>=entity.getMaxHealth()/2)part("Head",p,out,light,overlay,color);else{part("Skull",p,out,light,overlay,color);part("IOU",p,buffers.getBuffer(RenderType.entityCutout(ResourceLocation.parse("hbm:textures/entity/iou.png"))),light,overlay,color);}p.popPose();p.popPose();}private static void limb(String name,PoseStack p,VertexConsumer out,int light,int overlay,int color,float x,float y,float z,float angle){p.pushPose();p.translate(x,y,z);p.mulPose(Axis.ZP.rotationDegrees(angle));part(name,p,out,light,overlay,color);p.popPose();}}
